const SUPABASE_URL = 'https://SEU-PROJETO.supabase.co';
const SERVICE_ROLE = 'COLE_A_SERVICE_ROLE_AQUI';

const entrada = $input.first().json;

return [{
  json: {
    ...entrada,
    supabase_url: String(SUPABASE_URL).replace(/\/$/, ''),
    service_role: SERVICE_ROLE,
  },
}];

const entrada = $input.first().json;
const body = entrada.body && typeof entrada.body === 'object' ? entrada.body : entrada;
const atual = body.record || {};
const anterior = body.old_record || {};

if (body.type !== 'UPDATE' || atual.status !== 'concluido' || anterior.status === 'concluido' || !atual.id) {
  return [];
}

return [{
  json: {
    pedido_id: atual.id,
    supabase_url: entrada.supabase_url,
    service_role: entrada.service_role,
  },
}];

function reais(valor) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(valor) || 0);
}

function quando(iso, vazio) {
  if (!iso) return vazio;
  return new Intl.DateTimeFormat('pt-BR', {
    dateStyle: 'short',
    timeStyle: 'short',
    timeZone: 'America/Sao_Paulo',
  }).format(new Date(iso));
}

function numeroPedido(numero) {
  return '#' + String(numero).padStart(3, '0');
}

function clienteDoPedido(pedido) {
  const dados = pedido.clientes || {};
  const nome = dados.nome || 'Cliente não identificado';
  const email = String(dados.email || '').trim();
  if (!email) throw new Error('O cliente ' + nome + ' não tem e-mail cadastrado.');
  return { nome, email };
}

function primeiro(payload) {
  const lista = Array.isArray(payload) ? payload : [payload];
  return lista[0];
}

const FORMAS = {
  pix: 'Pix',
  cartao: 'Cartão',
  boleto: 'Boleto',
  dinheiro: 'Dinheiro',
  transferencia: 'Transferência',
  a_combinar: 'A combinar',
};

const pedido = primeiro($input.first().json);
if (!pedido || !pedido.id) {
  throw new Error('Pedido concluído não encontrado para registrar o faturamento.');
}

const cliente = clienteDoPedido(pedido);
const numero = numeroPedido(pedido.numero);
const valor = reais(pedido.valor_total);
const pagamento = FORMAS[pedido.forma_pagamento] || 'Não informada';

return [{
  json: {
    para: cliente.email,
    assunto: 'Pedido ' + numero + ' concluído — ' + valor + ' (' + pagamento + ')',
    corpo: [
      'Olá, ' + cliente.nome + '.',
      '',
      'Seu pedido foi concluído.',
      '',
      'Pedido: ' + numero,
      'Valor: ' + valor,
      'Pagamento: ' + pagamento,
      'Data: ' + quando(pedido.concluido_em || pedido.updated_at, 'sem data'),
    ].join('\n'),
  },
}];

const item = $input.first().json;
const mensagem = (item && item.error && item.error.message) || item.message || JSON.stringify(item);
throw new Error("Automação 3 não enviou o e-mail de faturamento: " + mensagem);
